"""Write local result page and desktop preview manifest after audit and rendering."""
import argparse,json,hashlib,html
from pathlib import Path
HERE=Path(__file__).resolve().parent
def main():
 p=argparse.ArgumentParser();p.add_argument('run',type=Path);a=p.parse_args();run=a.run.resolve()
 audit=json.loads((run/'evaluation.json').read_text());model=json.loads((run/'model.json').read_text());cfg=json.loads((run/'policy.json').read_text())
 for filename in ('policy.ts','training_replay.mp4','fresh_test.mp4'):
  if not (run/filename).is_file():raise ValueError(f'Missing deliverable: {filename}')
 rows=''
 for name,group in audit['groups'].items():
  s=group['summary'];rows+=f'<tr><td>{html.escape(name.replace("_"," "))}</td><td>{s["episodes"]}</td><td>{s["face_contacts"]}</td><td>{s["net_crossings"]}</td><td>{s["legal_returns"]}</td><td>{s["mean_deadline_error_cm"]:.1f}</td></tr>'
 sensitivity=''.join(f'<li>Step {s["physics_dt_s"]*1000:g} ms, attachment mass ×{s["attachment_mass_scale"]:g}: {"legal return" if s["report"]["legal_return"] else s["report"]["failure"] or "no legal return"}</li>' for s in audit['sensitivity'])
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>G1 · Hitting Plane to SONIC</title><style>body{margin:0;background:#101a29;color:#e5edf8;font:16px system-ui}main{max-width:1080px;margin:32px auto;padding:0 24px}h1{font-size:30px}p{line-height:1.55;color:#c8d6e6}video{width:100%;border-radius:12px;background:#050b14}section{background:#192638;padding:24px;border-radius:16px;margin:24px 0}a{color:#67d8ec}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #354256}small{color:#b0c0d0}.links{display:flex;gap:24px;flex-wrap:wrap}</style><main><h1>Hitting Plane → SONIC → Ball Return</h1><p>Direct wrist bracket · a four-input learned token policy · real MuJoCo contact dynamics.</p><div class="links"><a href="http://127.0.0.1:52180/">Open interactive 3D simulator</a><a href="policy.ts" download>Download model</a><a href="evaluation.json">Full audit</a></div><section><h2>Complete training-case replay</h2><p>XYZ = [0.43, −0.38, 0.178] m relative to the starting pelvis; hit time = 1.00 s. Half-speed replay of recorded physics; no browser WebGL needed.</p><video controls preload="metadata" poster="training_replay_impact.png" src="training_replay.mp4"></video></section><section><h2>Six consecutive fresh test cases</h2><p>The first six trials from the fixed fresh test seed, including any failures. This is not a selected-success montage.</p><video controls preload="metadata" poster="fresh_test_impact.png" src="fresh_test.mp4"></video></section><section><h2>Measured results</h2><table><thead><tr><th>Group</th><th>Trials</th><th>Hits</th><th>Net clears</th><th>Legal returns</th><th>Mean hit-point error (cm)</th></tr></thead><tbody>ROWS</tbody></table><p>The earlier nearby and wide groups were development checks. The fresh test uses 20 unseen target/time combinations. These small deterministic tests are not real-world success rates.</p><h3>Sensitivity checks</h3><ul>SENSITIVITY</ul></section><section><h2>Use the simulator</h2><p>In G1 Studio, select <b>Token Policy Sim → Hitting plane · Direct bracket → Start Token Simulation</b>. Set target Y/Z and time, then click <b>Run strike</b>. X is fixed at 0.43 m. If WebGL is unavailable, use <b>Open Simulation Replay</b>.</p><p>+X forward, +Y left, +Z up; metres and seconds. Z is relative to the starting pelvis, not the floor or table. During a stroke, keep XYZ fixed and decrease time-to-hit at 50 Hz; negative time drives follow-through.</p><h3>What is trained?</h3><p>A motion-token neural prior plus a low-rank token head refined using CEM reinforcement learning. The combined exported model takes [X,Y,Z,time] and outputs 64 SONIC token values. SONIC remains frozen and separately consumes joint/IMU history. The runtime does not invoke a motion encoder or assign reference joint positions during the swing.</p><h3>Scope</h3><p>Ready-pose initialization, one ball, ideal target/time inputs, a narrow forehand feed family, provisional 0.20 kg racket/bracket dynamics, no aerodynamic drag or spin. No hardware commands. This establishes a working simulation pipeline, not a validated hardware or general rally controller.</p><small>Model SHA-256: HASH</small></section></main></html>'''
 interactive='''<section><h2>Run a new simulation</h2><p>Enter a target and time. A fresh MuJoCo episode will run and its video will appear below. No WebGL required.</p><form id="strike"><label>X (m) <input value="0.43" disabled size="5"></label> <label>Y (m) <input name="y" type="number" min="-0.53" max="-0.33" step="0.001" value="-0.38" required></label> <label>Z (m) <input name="z" type="number" min="0.078" max="0.228" step="0.001" value="0.178" required></label> <label>Time (s) <input name="t" type="number" min="0.8" max="1" step="0.001" value="1" required></label> <button id="run" style="padding:10px 18px;margin:12px;background:#67d8ec;border:0;border-radius:8px">Run strike</button></form><p id="job" role="status">Ready · simulation only</p><video id="interactive" controls hidden></video></section><script>const f=document.getElementById('strike'),button=document.getElementById('run'),status=document.getElementById('job'),video=document.getElementById('interactive');f.onsubmit=async e=>{e.preventDefault();button.disabled=true;status.textContent='Running physics and rendering video…';try{const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({y_m:Number(f.elements.y.value),z_m:Number(f.elements.z.value),deadline_s:Number(f.elements.t.value)})});const start=await response.json();if(!response.ok)throw Error(start.error);let result;do{await new Promise(resolve=>setTimeout(resolve,500));result=await(await fetch('/api/job/'+start.job)).json();}while(result.status==='running');if(result.status==='error')throw Error(result.error);const r=result.report;status.textContent=(r.legal_return?'LEGAL RETURN':'NO LEGAL RETURN')+' · hit: '+r.face_contact+' · net: '+r.net_crossed+' · hit-point error: '+(r.face_error_at_deadline_cm?.toFixed(1)??'—')+' cm'+(r.failure?' · '+r.failure:'');video.src=result.video;video.hidden=false;video.load();video.play().catch(()=>{});}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};</script>'''
 page=page.replace('<section><h2>Complete training-case replay',interactive+'<section><h2>Complete training-case replay')
 (run/'index.html').write_text(page.replace('ROWS',rows).replace('SENSITIVITY',sensitivity).replace('HASH',model['sha256']))
 (HERE.parent/'hitting-plane-preview.json').write_text(json.dumps({'run':str(run),'model_sha256':model['sha256'],'simulation_only':True,'hardware_approved':False,'viewer':'hitting_plane/serve.py'},indent=2))
 print(run/'index.html')
if __name__=='__main__':main()
